import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    max_pairs = k * (k - 1)
    if n > max_pairs:
        print("NO")
        return

    print("YES")

    pairs = []
    diff = 1
    while len(pairs) < n:
        for start_b in range(1, k + 1):
            if len(pairs) >= n:
                break
            start_g = (start_b + diff - 1) % k + 1
            if start_g == start_b:
                continue

            current_b = start_b
            current_g = start_g

            while True:
                if len(pairs) >= n:
                    break

                if current_b == current_g:
                    break

                pairs.append((current_b, current_g))

                next_b = current_b + 1
                next_g = current_g + 1

                if next_b > k:
                    break
                if next_g > k:
                    break

                current_b = next_b
                current_g = next_g

        diff += 1
        if diff >= k:
            break

    for b, g in pairs:
        print(f"{b} {g}")

if __name__ == "__main__":
    solve()
